test('vatSummary returns VAT grouped by rate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const invoices = [i1.value];

  const result = vatSummary(invoices);
  assert(result.length > 0);
  assert.equal(result[0].rate, 21);
  assert(result[0].base > 0);
  assert(result[0].vat > 0);
});

test('vatSummary groups multiple lines by rate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 50, discountPercent: 0 },
    ],
  });

  const i1 = issueInvoice(r1.value, []);
  const invoices = [i1.value];

  const result = vatSummary(invoices);
  const rate21 = result.find((r) => r.rate === 21);
  const rate9 = result.find((r) => r.rate === 9);

  assert(rate21);
  assert(rate9);
});

test('vatSummary sorts by rate descending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 50, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 },
    ],
  });

  const i1 = issueInvoice(r1.value, []);
  const invoices = [i1.value];

  const result = vatSummary(invoices);
  for (let i = 0; i < result.length - 1; i++) {
    assert(result[i].rate >= result[i + 1].rate);
  }
});

