test('vatSummary calculates base correctly (after discount)', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const invoices = [i1.value];

  const result = vatSummary(invoices);
  const rate21 = result.find((r) => r.rate === 21);

  const lineTotal = 10 * 8500;
  const discount = Math.round(lineTotal * 10 / 100);
  const expectedBase = lineTotal - discount;

  assert(Math.abs(rate21.base - expectedBase) < 10);
});

