  const i2 = issueInvoice(r2.value, ['INV-2026-0001']);

  const invoices = [i1.value, i2.value];

  const result = vatSummary(invoices);
  const rate21 = result.find((r) => r.rate === 21);

  const line1Base = (5 * 8500);
  const line2Base = (3 * 9500);
  const expectedBase = line1Base + line2Base;

  assert(Math.abs(rate21.base - expectedBase) < 10);
});

